/*
 * pc/hal/file_id.c — runtime file_id (LBA) resolver.
 *
 * The static lookup table g_file_lba_table is generated by
 * pc/tools/build_lba_map.py from the disc image and committed as
 * pc/src/file_lba_table.c. We binary-search it by LBA at runtime.
 */
#include "file_id.h"
#include "pc_data_root.h"
#include "nbn_trace.h"
#include "lang.h"
#include <stdio.h>
#include <string.h>

const FileLbaEntry *file_id_lookup_lba(u32 lba) {
    /* Binary search assumes the table is sorted by LBA. The Python
     * generator emits entries sorted by path (alphabetical), so we
     * fall back to linear scan. The table has ~1400 entries — at most
     * ~50 µs per call, fine for occasional file loads. */
    for (u32 i = 0; i < g_file_lba_table_count; i++) {
        if (g_file_lba_table[i].lba == lba) {
            return &g_file_lba_table[i];
        }
    }
    return NULL;
}

u32 file_id_load_by_lba(u32 lba, void *dest, u32 cap) {
    const FileLbaEntry *e = file_id_lookup_lba(lba);
    if (!e) {
        printf("[file_id] no file at LBA %u (= 0x%X)\n", lba, lba);
        return 0;
    }
    char path[1024];
    snprintf(path, sizeof(path), "%s/raw/%s", pc_asset_dir(), e->path);
    char en[1024];
    FILE *f = fopen(lang_path(path, en, sizeof en), "rb");
    if (!f) {
        printf("[file_id] cannot open: %s\n", path);
        return 0;
    }
    u32 to_read = (cap < e->size) ? cap : e->size;
    size_t got = fread(dest, 1, to_read, f);
    fclose(f);
    nbn_trace_register_load(e->path, dest, 0, (u32)got);
    return (u32)got;
}
